 const float before=car.Mechanical().damage[mechanicalmodel::kEngine];auto shot=car.Bullet({0,13,.45f},{0,10,.45f},200);Check(shot.valid&&shot.changed&&car.Mechanical().damage[mechanicalmodel::kEngine]>before,"nose bullet damages canonical local automobile engine");Check(car.Mechanical().damage[mechanicalmodel::kFuel]==0,"nose shot cannot remotely damage aft fuel");auto fire=car.Fire(true);Check(fire.engine>0&&fire.breach==0,"fire reads same canonical engine and isolated fuel");
 const auto revision=car.Revision();auto miss=car.Bullet({0,3,.45f},{0,0,.45f},200);Check(miss.valid&&!miss.changed&&car.Revision()==revision,"old Dodo engine coordinates have no phantom generic hit");float closest=1;Vec3 normal;Check(!car.TraceComponent({0,3,.45f},{0,0,.45f},0,closest,normal),"component trace cannot hit outside actual surviving body");
 Model armored;auto armor=Define(Kind::Automobile);armor.armor=4;Check(armored.Initialize(Hull(),1200,armor),"effective armor initializes");auto stopped=armored.Bullet({0,13,.45f},{0,11.8f,.45f},20);Check(stopped.valid&&stopped.remaining==0&&armored.Mechanical().damage[mechanicalmodel::kEngine]==0,"effective armor absorbs surface work before engine");
 Model wheels;auto d=Define(Kind::Automobile);d.hasWheels=true;d.wheels={Vec3{-1,11.2f,0},Vec3{-1,8.8f,0},Vec3{1,11.2f,0},Vec3{1,8.8f,0}};auto s=Hull();Quad(s,{-.99f,11,-.2f},{-.99f,11.4f,-.2f},{-.99f,11.4f,.2f},{-.99f,11,.2f},10,Role::Wheel);Check(wheels.Initialize(s,1200,d),"actual wheel positions initialize");auto wheelHit=wheels.Bullet({-2,11.2f,0},{-.7f,11.2f,0},200);Check(wheelHit.valid&&wheels.Mechanical().damage[mechanicalmodel::kWheelLF]>0,"wheel shot uses shared local component work");Check(wheels.Mechanical().damage[mechanicalmodel::kWheelRR]==0,"opposite wheel remains isolated");
