 Model nativePlane;Check(nativePlane.Initialize(Hull(),100000000,Define(Kind::Plane))&&nativePlane.SetMass(99999984.f),"prescribed-motion native aircraft retain their actual large carrier mass");
 std::vector<aircraftconnectivity::Face> joined{{{{Vec3{0,0,0},Vec3{1,0,0},Vec3{0,1,0}}},0},{{{Vec3{2,0,0},Vec3{3,0,0},Vec3{2,1,0}}},1}};
 aircraftconnectivity::Mesh supported;std::vector<aircraftconnectivity::Support> supports{{{1,{2.05f,.4f,0}},{0,{.5f,.4f,0}}}};Check(supported.Build(joined,{{0,{.1f,.1f,0}}},{},supports),"disjoint material part mounts on real parent material");Check(supported.Fragments().size()==2&&supported.Fragments()[1].attached,"supported disjoint part starts attached");Check(supported.ApplyHole({{.5f,.4f,0},{0,0,1},.1f},0),"parent support can be locally removed");bool partAttached=false;for(const auto&f:supported.Fragments())if(f.group==1)partAttached|=f.attached;Check(!partAttached,"removing parent mount releases disjoint child without a phantom independent root");
 auto unnamed=Hull();Quad(unnamed,{1,9.6f,.6f},{5,9.6f,.6f},{5,10.4f,.6f},{1,10.4f,.6f});Quad(unnamed,{-5,9.6f,.6f},{-1,9.6f,.6f},{-1,10.4f,.6f},{-5,10.4f,.6f});auto air=Define(Kind::Plane);air.bounds.lo.x=-5;air.bounds.hi.x=5;Model inferred;Check(inferred.Initialize(unnamed,1200,air),"unnamed aircraft skin initializes without Dodo coordinates");bool inferredLeft=false,inferredRight=false;for(const auto&s:inferred.Surfaces()){inferredLeft|=s.role==Role::WingLeft;inferredRight|=s.role==Role::WingRight;}Check(inferredLeft&&inferredRight&&std::fabs(inferred.Layout().beams[1].span-4)<.01f,"actual transverse sections identify unnamed wings and measured span");auto wingShot=inferred.Bullet({4,10,2},{4,10,.3f},200);Check(wingShot.valid&&inferred.Effects().rightLift<1&&inferred.Fire(false).engine==0,"inferred wing material loss reduces only local lift");
 Model airTires;auto airWheelDefinition=d;airWheelDefinition.kind=Kind::Plane;Check(airTires.Initialize(s,1400,airWheelDefinition),"aircraft actual wheel geometry shares canonical tire mechanics");auto airTireHit=airTires.Bullet({-2,11.15f,.05f},{-.7f,11.15f,.05f},200);const auto&airMechanics=airTires.Mechanical();const float tireWork=airMechanics.damage[mechanicalmodel::kWheelLF]*40+airMechanics.damage[mechanicalmodel::kBrakeLF]*12;Check(airTireHit.valid&&airMechanics.damage[mechanicalmodel::kWheelLF]>0&&airMechanics.damage[mechanicalmodel::kBrakeLF]>0&&tireWork<=airTireHit.deposited+.0001f&&airMechanics.damage[mechanicalmodel::kWheelRR]==0,"aircraft tire and brake split exactly accepted local wheel sheet work");
