 aircraftconnectivity::Mesh cycle;Check(cycle.Build(joined,{},{},{{{1,{2.05f,.4f,0}},{0,{.5f,.4f,0}}},{{0,{.5f,.4f,0}},{1,{2.05f,.4f,0}}}}),"cyclic mount topology remains a valid finite graph");bool cycleAttached=false;for(const auto&f:cycle.Fragments())cycleAttached|=f.attached;Check(!cycleAttached,"a mount cycle cannot create its own support without retained body material");
 // Native doors, glazing and tires are real collision sheets even though
 // none may contribute a fictitious load-bearing beam section.
 auto attachedArea=[](const Model&m,uint32_t group,bool structuralOnly=false){float area=0;for(const auto&f:m.Fragments())if(f.attached&&f.group==group&&(!structuralOnly||m.Surfaces()[f.source].structural))for(size_t k=1;k+1<f.polygon.size();++k){const auto a=f.polygon[0].position,b=f.polygon[k].position,c=f.polygon[k+1].position;const Vec3 u{b.x-a.x,b.y-a.y,b.z-a.z},v{c.x-a.x,c.y-a.y,c.z-a.z};const Vec3 n{u.y*v.z-u.z*v.y,u.z*v.x-u.x*v.z,u.x*v.y-u.y*v.x};area+=.5f*std::sqrt(n.x*n.x+n.y*n.y+n.z*n.z);}return area;};
 Model doorContact,glassContact,tireContact;std::array<Model*,3> parts{{&doorContact,&glassContact,&tireContact}};std::array<float,3> lostArea{};
 for(int part=0;part<3;++part){auto sheets=Hull();Quad(sheets,{-1.6f,9.4f,.1f},{-1.6f,10.6f,.1f},{-1.6f,10.6f,.9f},{-1.6f,9.4f,.9f},20,part==0?Role::Door:part==1?Role::Body:Role::Wheel);for(auto&face:sheets)if(face.group==20){face.structural=false;face.glass=part==1;}auto definition=Define(Kind::Automobile);definition.bounds.lo.x=-1.7f;definition.hasWheels=part==2;definition.wheels={Vec3{-1.6f,10,.5f},Vec3{-1,8.8f,0},Vec3{1,11.2f,0},Vec3{1,8.8f,0}};auto&m=*parts[part];Check(m.Initialize(sheets,1200,definition),"actual nonstructural contact sheet initializes");const float before=attachedArea(m,20);const auto receipt=m.ContactEnergy({-1.61f,10.2f,.6f},{1,0,0},part==2?50:100,1000,.02f);lostArea[part]=before-attachedArea(m,20);Check(receipt.valid&&receipt.changed&&receipt.holes>0&&lostArea[part]>0,"contact spends finite local work on door/glass/tire material");const auto chassis=m.Deform({0,11,.5f},0);Check(std::fabs(chassis.x)<1e-7f&&chassis.y==11&&chassis.z==.5f,"nonstructural contact cannot deform the load-bearing chassis beam");Check(m.Fire(false).engine==0&&m.Fire(false).breach==0,"isolated outer sheet contact cannot damage distant engine or fuel");if(part==0){bool dented=false;for(const auto&f:m.Fragments())if(f.attached&&f.group==20)for(auto v:f.polygon)dented|=m.Deform(v.position,20).x>v.position.x+.001f;Check(dented,"door's surviving material carries a local plastic dent");}if(part==2)Check(m.Mechanical().damage[mechanicalmodel::kWheelLF]>0&&m.Mechanical().damage[mechanicalmodel::kWheelRR]==0,"tire contact changes only its canonical local wheel mechanics");}
 Check(lostArea[1]>lostArea[0],"glass and steel require distinct material fracture work");
 auto release=glassContact.ContactEnergy({-1.61f,10,.5f},{1,0,0},1000,2000,.02f);std::vector<aircraftconnectivity::Fragment> brokenPane;Check(release.valid&&release.changed&&glassContact.TransferDetached(brokenPane)&&!brokenPane.empty(),"contact fracture releases a disjoint pane when its real material mount is cut");Check(attachedArea(glassContact,0)>10,"pane mount failure preserves retained chassis material");
 auto interiorSheets=Hull();Quad(interiorSheets,{-1.6f,9.4f,.1f},{-1.6f,10.6f,.1f},{-1.6f,10.6f,.9f},{-1.6f,9.4f,.9f},30,Role::Interior);for(auto&face:interiorSheets)if(face.group==30)face.structural=false;Model interiorContact;auto interiorDefinition=Define(Kind::Automobile);interiorDefinition.bounds.lo.x=-1.7f;Check(interiorContact.Initialize(interiorSheets,1200,interiorDefinition),"interior trim fixture initializes");Check(!interiorContact.ContactEnergy({-1.61f,10.2f,.6f},{1,0,0},400,1000,.02f).valid,"interior trim cannot manufacture an exterior contact patch");
 auto mixedSheets=Hull();Quad(mixedSheets,{-1.6f,9.4f,.1f},{-1.6f,10.6f,.1f},{-1.6f,10.6f,.9f},{-1.6f,9.4f,.9f},50);for(auto&face:mixedSheets)if(face.group==50){face.structural=false;face.glass=true;}Quad(mixedSheets,{-1.6f,10.25f,.4f},{-1.6f,10.55f,.4f},{-1.6f,10.55f,.8f},{-1.6f,10.25f,.8f},50);Model mixedContact;Check(mixedContact.Initialize(mixedSheets,1200,interiorDefinition),"glass and structural frame may share an exported atomic");const auto frameArea=attachedArea(mixedContact,50,true);auto mixedHit=mixedContact.ContactEnergy({-1.61f,10.2f,.6f},{1,0,0},100,1000,.02f);Check(mixedHit.valid&&mixedHit.changed&&std::fabs(attachedArea(mixedContact,50,true)-frameArea)<.000001f,"glass fracture work cannot cut neighboring steel in the same source atomic");
auto mixedMountHit=mixedContact.ContactEnergy({-1.61f,10,.5f},{1,0,0},1000,2000,.02f);Check(mixedMountHit.valid&&std::fabs(attachedArea(mixedContact,50,true)-frameArea)<.000001f,"a mixed atomic's real opaque frame mount cannot depend on breakable glazing");
